const CORE=['./','./index.html','./style.css','./soft.css','./winter.css','./aurora.css','./metaverse.css','./glass.css','./ui-system.css','./luminous-loading.css','./customization.css','./mobile-ui.css','./fonts/PretendardVariable.woff2','./textures/loading-world.webp','./textures/moon-lroc.jpg','./textures/winter-world-map.webp','./vendor/three.module.js',...scripts.map(n=>'./'+n+'.js'),...['science','reasoning','humanities','perspectives','everyday','daily-trivia'].map(n=>'./content/'+n+'.json')];
const assetPaths=new Set(CORE.map(p=>new URL(p,self.location.href).pathname));
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(CORE)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>(key.startsWith('knowledge-campus-')||key.startsWith('knowledge-park-'))&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||!assetPaths.has(url.pathname))return;const cacheKey=new Request(url.origin+url.pathname);event.respondWith(fetch(event.request).then(async response=>{if(response.ok&&!response.redirected){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(cacheKey,copy)).catch(()=>{});}if(response.status>=500)return(await caches.match(cacheKey))||response;return response;}).catch(async()=>{const cached=await caches.match(cacheKey);return cached||new Response('연결을 확인하고 다시 시도해 주세요.',{status:503});}));});
